use std::time::Instant;


macro_rules! call_telemetry {
    ($name:literal, $call:expr) => {{
        let start = Instant::now();
        println!("🎯 CALL: {}", $name);
        let result = $call;
        let duration = start.elapsed().as_micros();
        println!("📊 DONE: {} ({}μs)", $name, duration);
        result
    }};
}

